#!/bin/bash
# launch-codex.sh <ID> <prompt> — Codex worker pane on gpt-6-sol (default worker since 2026-09-23 evening). The suffix carries the write-scope and stop-rule clarifications Codex needs.
ID=$1; PROMPT=$2; name=$(echo "$ID" | tr A-Z a-z)
pane=$(herdr tab create --workspace ${WS:-w2} --cwd ~/dev/ssx3 --label "$ID" | python3 -c 'import json,sys;print(json.load(sys.stdin)["result"]["root_pane"]["pane_id"])')
sleep 4; herdr agent start "$name" --kind codex --pane "$pane" --timeout 120000 -- -m gpt-6-sol -c model_reasoning_effort=medium --approve-for-me -c sandbox_workspace_write.network_access=true --add-dir ~/dev/ssx3-work --add-dir ~/dev/PS2Recomp --add-dir /tmp >/dev/null || { echo "$ID start failed"; exit 1; }; sleep 10
herdr agent prompt "$name" "$PROMPT Commit trailer for this brief: 'Orchestrated-By: Codex'. You are a worker on a brief: follow ~/dev/AGENTS.md worker rules (touch only what the brief allows; on a denial or first failure, stop and report). Write scope: the brief is your authorization for the paths it names — ~/dev/ssx3 (report dir + commit), ~/dev/ssx3-work dirs it names, local worktrees/branches of ~/dev/PS2Recomp it names (no push unless the brief explicitly authorizes a fast-forward fork push after the runner-dir check), and the lease files via local/tooling/p_lane_lease.py count as inside your started folder; all else read-only. Stop rule: \"first failure\" means a failed BRIEF STEP (build after one fix attempt, test/gate, boot crash, or an escalation request the reviewer denies). Both mini lease slots busy is NOT a failure: poll `python3 local/tooling/p_lane_lease.py status` every 60 s and boot when a slot frees, not your own exploratory command errors (wrong path, typo) — fix those and keep going. Fork paths in briefs are relative to the fork worktree. Run ps2x_tests from the fork worktree root (it reads source files by relative path; from elsewhere a VU0-mapping test fails spuriously). Sandbox: you run in a workspace-write sandbox with automatic review. When a command fails because of the sandbox (Operation not permitted, .git/index.lock, network), request escalated permissions and rerun it; that is not a failure. Run every git write in a fork worktree (its .git is protected) and every game/runner boot (the runner hangs at graphics init inside the sandbox) with escalated permissions from the start." --wait --until working --timeout 30000 | python3 -c 'import json,sys;r=json.load(sys.stdin)["result"]["agent"];print(r["name"],r["pane_id"],r["agent_status"])'
